  "latex": "(i_{x, *}A)_{x'} = \\left\\{ \\begin{matrix} A & \\text{if} & x' \\in \\overline{\\{x\\}} \\\\ \\{*\\} & \\text{if} & x' \\not\\in \\overline{\\{x\\}} \\end{matrix} \\right.",
  "name": "lemma · Skyscraper sheaves and stalks",
